/**
 * Database access: one `Db` type behind two drivers.
 *
 * - `DATABASE_URL` set → Postgres through postgres-js (Neon in production).
 * - unset → PGlite (Postgres compiled to WASM) persisted under `.data/pglite`
 *   locally, or in memory for tests and read-only hosts.
 *
 * Migrations (`database/migrations`, generated by drizzle-kit and bundled into
 * `bundle.ts`) are applied at startup through the same code path for both.
 */
import { sql } from "drizzle-orm";
import type { PgDatabase, PgQueryResultHKT } from "drizzle-orm/pg-core";
import * as schema from "../../../database/schema";
import { migrations } from "../../../database/migrations/bundle";

export { schema };
export type Db = PgDatabase<PgQueryResultHKT, typeof schema>;
export type DatabaseKind = "postgres" | "pglite";

export interface DbHandle {
  db: Db;
  kind: DatabaseKind;
  close(): Promise<void>;
}

export interface DbOptions {
  /** Postgres connection string. Takes precedence over PGlite. */
  url?: string;
  /** PGlite data directory, or `"memory"` for an ephemeral database. */
  pglite?: string | "memory";
}

/** Open a database and bring its schema up to date. */
export async function openDb(options: DbOptions): Promise<DbHandle> {
  const handle = options.url
    ? await openPostgres(options.url)
    : await openPglite(options.pglite);
  await applyMigrations(handle.db);
  return handle;
}

async function openPostgres(url: string): Promise<DbHandle> {
  const [{ default: postgres }, { drizzle }] = await Promise.all([
    import("postgres"),
    import("drizzle-orm/postgres-js"),
  ]);
  const client = postgres(url, { max: 5, prepare: false });
  const db = drizzle(client, { schema });
  return { db, kind: "postgres", close: () => client.end() };
}

async function openPglite(dataDir: string | "memory" = "memory"): Promise<DbHandle> {
  const [{ PGlite }, { drizzle }] = await Promise.all([
    import("@electric-sql/pglite"),
    import("drizzle-orm/pglite"),
  ]);
  if (dataDir !== "memory") {
    // PGlite creates only the last path segment itself.
    const { mkdir } = await import("node:fs/promises");
    await mkdir(dataDir, { recursive: true });
  }
  const client = dataDir === "memory" ? new PGlite() : new PGlite(dataDir);
  await client.waitReady;
  const db = drizzle(client, { schema });
  return { db, kind: "pglite", close: () => client.close() };
}

/**
 * Apply every bundled migration that has not been recorded yet. Each
 * migration runs in its own transaction and is recorded by tag, so a restart
 * mid-way never applies a statement twice.
 */
export async function applyMigrations(db: Db): Promise<void> {
  await db.execute(
    sql`CREATE TABLE IF NOT EXISTS "bona_migrations" ("tag" text PRIMARY KEY, "hash" text NOT NULL, "applied_at" text NOT NULL)`,
  );
  const applied = new Set(
    rowsOf(await db.execute(sql`SELECT "tag" FROM "bona_migrations"`)).map((r) => r.tag),
  );
  for (const migration of migrations) {
    if (applied.has(migration.tag)) continue;
    await db.transaction(async (tx) => {
      for (const statement of migration.statements) {
        if (statement.trim()) await tx.execute(sql.raw(statement));
      }
      await tx.execute(
        sql`INSERT INTO "bona_migrations" ("tag", "hash", "applied_at") VALUES (${migration.tag}, ${migration.hash}, ${new Date().toISOString()})`,
      );
    });
  }
}

/** postgres-js returns an array; PGlite returns `{ rows }`. */
function rowsOf(result: unknown): Array<Record<string, string>> {
  if (Array.isArray(result)) return result as Array<Record<string, string>>;
  const rows = (result as { rows?: unknown }).rows;
  return Array.isArray(rows) ? (rows as Array<Record<string, string>>) : [];
}
